import {createStudioProject,normalizeStudioProject,makePart,addConnection,partTransforms,transformPoint,applyStudioProposal,validateStudio,projectBounds,unitsPerMm} from './studio-model.mjs';
import {renderStudioSvg,exportSheetSvg,exportPrintHtml,getFabricationMetrics} from './studio-render.mjs';
import {saveStudioProject,loadStudioProject,serializeStudioProject,parseStudioProject,readArtworkFile} from './studio-storage.mjs';
import {requestStudioAI,getStudioCapabilities} from './studio-ai.mjs';
import {createStarter} from './studio-starters.mjs';
import {resizePart,setPartParameterAxis,getPartParameters,preservePhysicalScale} from './studio-parametric.mjs';
import {removeConnectedBackground,selectImageRegion,extractImageSilhouette,decodeArtwork,assetFromImageData} from './studio-image-tools.mjs';
import {splitPart,suggestConnection} from './studio-construction.mjs';

const root=document.querySelector('#app');
const state={project:createStudioProject(),step:'create',selected:null,mode:'select',points:[],jointStart:null,jointType:'pivot',showArt:true,showJoints:true,showConcept:true,undo:[],redo:[],proposal:null,proposalBase:null,proposalLabel:'',proposalAfter:null,proposalVersion:null,reply:'',messages:[],prompt:'',revisionPrompt:'',busy:false,capabilities:null,saveStatus:'loading',error:'',help:false,settings:false,endpoint:'',version:0,imageTolerance:30,imageRaster:null,imageRasterId:null,connectParent:''};
let saveTimer,saveChain=Promise.resolve(),controller,drag=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=(en,zh)=>state.project.language==='zh'?zh:en;
const selected=()=>state.project.parts.find(p=>p.id===state.selected);
const uid=()=>globalThis.crypto?.randomUUID?.()||'p-'+Date.now()+'-'+Math.random().toString(36).slice(2);
const btn=(label,action,cls='',disabled=false,extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${disabled?'disabled':''} ${extra}>${label}</button>`;
const field=(label,content)=>`<label class="field"><span>${label}</span>${content}</label>`;
function selectField(key,label,options,value,attrs=''){return field(label,`<select data-field="${key}" ${attrs}>${options.map(([v,en,zh])=>`<option value="${esc(v)}" ${value===v?'selected':''}>${esc(t(en,zh||en))}</option>`).join('')}</select>`);}
function status(){const el=document.querySelector('#save-status');if(el)el.textContent=({loading:t('Opening…','正在打开…'),saved:t('Saved on this device','已保存在此设备'),saving:t('Saving…','正在保存…'),unsaved:t('Download to keep your work','请下载保存作品'),error:t('Autosave unavailable · download project','无法自动保存 · 请下载项目')})[state.saveStatus]||'';}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');setTimeout(()=>el.classList.remove('visible'),4500);}
function scheduleSave(){state.saveStatus='saving';status();clearTimeout(saveTimer);const version=state.version,project=state.project;saveTimer=setTimeout(()=>{saveChain=saveChain.catch(()=>{}).then(()=>saveStudioProject(project)).then(()=>{if(version===state.version){state.saveStatus='saved';status();}}).catch(()=>{state.saveStatus='error';status();});},500);}
function commit(next,label=t('Edit','编辑')){const normalized=normalizeStudioProject(next);const before=partTransforms(state.project),after=partTransforms(normalized);for(const part of state.project.parts.filter(p=>p.locked)){const other=normalized.parts.find(p=>p.id===part.id);if(other?.locked&&(JSON.stringify(part)!==JSON.stringify(other)||before[part.id].some((n,i)=>Math.abs(n-after[part.id][i])>.001)))throw Error(t('This would change a locked part. Unlock it first.','此修改会影响已锁定部件，请先解锁。'));}state.undo.push(state.project);if(state.undo.length>16)state.undo.shift();state.redo=[];state.project=normalized;state.project.revisions=[...(state.project.revisions||[]).slice(-19),{id:uid(),createdAt:new Date().toISOString(),label}];state.version++;state.proposal=null;state.error='';if(!state.project.parts.some(p=>p.id===state.selected))state.selected=null;scheduleSave();render();}
function mutate(fn,label,{keepScale=true}={}){let next=structuredClone(state.project);fn(next);if(keepScale&&(state.project.parts.length||next.parts.length))next=preservePhysicalScale(state.project,next);commit(next,label);}
function resetTool(){state.mode='select';state.points=[];state.jointStart=null;}
function download(name,contents,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([contents],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function safeName(){return (state.project.title.trim()||'shadow-puppet').replace(/[^\p{L}\p{N}_-]+/gu,'-').slice(0,60);}
function beginTool(mode){resetTool();state.mode=mode;if(mode==='joint'||mode==='rod')state.selected=null;state.step='make';render();}

function conceptAsset(){return state.project.assets.find(a=>a.id===state.project.conceptAssetId);}
function proposeLocal(project,label,reply,after={}){state.proposal=normalizeStudioProject(project);state.proposalBase=structuredClone(state.project);state.proposalLabel=label;state.proposalAfter=after;state.proposalVersion=state.version;state.reply=reply;state.error='';render();}
async function currentRaster(){const asset=conceptAsset();if(!asset)throw Error(t('Import an artwork image first.','请先导入作品图片。'));if(state.imageRasterId!==asset.id){const data=await decodeArtwork(asset);state.imageRaster=data;state.imageRasterId=asset.id;}return state.imageRaster;}
function imageToolsPanel(){const asset=conceptAsset();if(!asset)return '';return `<section class="image-tools"><div class="panel-heading"><h3>${t('Image to pieces','图片转为部件')}</h3><span class="local-badge">${t('On this device','本地处理')}</span></div><p>${t('Use a plain background or transparent PNG. Connected areas become one piece; split them where you want movement.','建议使用纯色背景或透明 PNG。连通区域会形成一个部件，可在需要活动的位置分割。')}</p>${state.project.assets.length>1?field(t('Source image','原始图像'),`<select data-source-art>${state.project.assets.map(a=>`<option value="${esc(a.id)}" ${a.id===asset.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select>`):''}${field(t('Image selection tolerance','图像选择容差'),`<input type="range" data-image-tolerance min="0" max="100" step="1" value="${state.imageTolerance}" aria-label="${t('Image selection tolerance','图像选择容差')}"><output id="tolerance-output">${state.imageTolerance}</output>`)}<div class="tool-stack">${btn(t('Remove plain background','去除纯色背景'),'remove-background','secondary',state.busy)}${btn(t('Find silhouette pieces','提取轮廓部件'),'extract-silhouette','secondary',state.busy)}${btn(t('Click to select a color region','点击选择颜色区域'),'select-region',state.mode==='region'?'tool active':'tool',state.busy)}</div><p class="fine-print">${t('These are image tools, not AI recognition. Review every result before accepting. Paint details stay in the artwork.','这些是图像处理工具，不是 AI 识别。请先检查结果再接受。绘画细节会保留在图像中。')}</p></section>`;}
function dimensionControls(part){const info=getPartParameters(state.project,part.id);return `<section class="dimension-controls"><h3>${t('Shape & proportions','形状与比例')}</h3><p>${t('Artwork stretches with its outline. Attached pieces follow their joints.','图像随轮廓一起伸缩，连接部件会跟随关节位置移动。')}</p>${[['width','Width','宽度'],['length','Length','长度']].map(([key,en,zh])=>field(t(en,zh)+` <output id="parameter-${key}-output">${Math.round(info[key]*100)}%</output>`,`<input type="range" data-param-field="${key}" min="25" max="400" step="1" value="${Math.round(info[key]*100)}" ${part.locked?'disabled':''}>`)).join('')}<div class="dimension-readout">${Number(info.widthMm).toFixed(1)} × ${Number(info.lengthMm).toFixed(1)} mm</div><div class="two-fields">${field(t('Length direction · °','长度方向 · °'),`<input type="number" data-param-axis min="-180" max="180" step="1" value="${Math.round(info.axisAngle)}" ${part.locked?'disabled':''}>`)}<div class="axis-help">${t('0° = vertical<br>90° = horizontal','0° = 竖直<br>90° = 水平')}</div></div>${btn(t('Set direction on the piece','在部件上设置方向'),'parameter-axis','secondary full',part.locked)}<p class="fine-print">${t('Changing direction keeps the current shape and starts new percentages at 100%. Undo restores previous changes.','更改方向会保持当前形状，并将比例重新设为 100%。撤销可恢复之前的修改。')}</p></section>`;}
function connectionSuggestion(part){if(state.project.joints.some(j=>j.childId===part.id)||state.project.parts.length<2)return '';const parents=state.project.parts.filter(p=>p.id!==part.id&&!p.locked);return `<details class="connection-suggestion"><summary>${t('Suggest a pivot connection','建议旋转连接')}</summary><p>${t('Choose the piece this part should attach to. A nearby pivot will be proposed for review.','选择此部件要连接的父部件，系统将建议附近的转轴位置供你审核。')}</p><select data-connect-parent aria-label="${t('Parent part','父部件')}"><option value="">${t('Choose parent part','选择父部件')}</option>${parents.map(p=>`<option value="${esc(p.id)}" ${state.connectParent===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select>${btn(t('Suggest connection','建议连接'),'suggest-connection','secondary full',part.locked||!parents.some(p=>p.id===state.connectParent))}</details>`;}
async function runImageTool(action,seed){if(state.busy)return;state.busy=true;state.error='';const version=state.version;render();try{const asset=conceptAsset(),raster=await currentRaster();if(version!==state.version)throw Error(t('The project changed. Try this image action again.','项目已改变，请重新操作。'));let next=structuredClone(state.project),reply='',after={showConcept:true,imageReview:true};
if(action==='remove-background'){const result=removeConnectedBackground(raster,{tolerance:state.imageTolerance});if(!result.removedPixels)throw Error(t('No connected plain background was found. Try a different tolerance, select a region, or trace the outline.','未找到连通的纯色背景。请调整容差、选择区域或手动描绘轮廓。'));const cleaned=await assetFromImageData(result,{name:asset.name+' '+t('(background removed)','（已去除背景）')});if(version!==state.version)throw Error(t('The project changed. Try again.','项目已改变，请重试。'));next.assets.push(cleaned);next.conceptAssetId=cleaned.id;for(const p of next.parts)if(p.assetId===asset.id&&!p.locked)p.assetId=cleaned.id;reply=t('Review the transparent areas. Only background connected to the image edge was removed; connected white clothing can also be affected. Your original image is kept.','请检查透明区域。处理仅去除与图像边缘相连的背景，但相连的白色服装也可能受影响。已保留原图。')+' '+(result.warnings||[]).join(' ');}
else{const result=action==='select-region'?selectImageRegion(raster,seed,{tolerance:state.imageTolerance}):extractImageSilhouette(raster,{minArea:Math.max(16,Math.round(raster.width*raster.height*.00005)),maxParts:40});const regions=action==='select-region'?[result]:result.parts;if(!regions.length)throw Error((result.warnings||[]).join(' ')||t('No usable region was found. Trace the outline manually.','未找到可用区域，请手动描绘轮廓。'));if(action==='extract-silhouette'&&regions.length===1&&regions[0].pixelCount>raster.width*raster.height*.97)throw Error(t('The image still has an opaque background. Remove the background first, or select a color region.','图像仍有不透明背景。请先去除背景，或选择颜色区域。'));if(next.parts.length+regions.length>80)throw Error(t('Too many pieces. Select smaller groups or remove unused pieces first.','部件过多。请先选择较小区域或删除不用的部件。'));const names=[];for(const region of regions){const part=makePart(t('Image piece ','图像部件 ')+(next.parts.length+1),region.polygon,asset.id);part.z=next.parts.length;next.parts.push(part);names.push(part.id);}next=preservePhysicalScale(state.project,next);after={showArt:true,showConcept:false,selected:names[0],step:'make'};reply=t('Review the extracted cut boundaries. Connected regions are not anatomical parts yet: split them at elbows, knees, or other movement points. Interior transparent details remain artwork, not automatic cutouts.','请检查提取的裁切轮廓。连通区域还不是解剖部件：可在肘、膝或其他活动位置分割。内部透明细节保留在图像中，不会自动变为镂空裁切。')+' '+(result.warnings||[]).join(' ');}
resetTool();proposeLocal(next,action==='remove-background'?t('Remove image background','去除图像背景'):t('Extract image pieces','提取图像部件'),reply,after);
}catch(error){state.error=error.message;}finally{state.busy=false;render();}}

function createPanel(){const b=state.project.brief;return `<div class="eyebrow">${t('01 / Find your character','01 / 构思角色')}</div><h1>${t('Who will step<br>into the light?','谁将走进<br>光影世界？')}</h1><p class="intro">${t('Start with your own idea, an image, or a simple construction template.','从自己的想法、图片或简单结构模板开始。')}</p>
${state.capabilities?.mode==='drawing-plan'?`<p class="connection-note">${t('Connected in compatibility mode. AI plans may need correction; imported artwork keeps your exact visual design.','当前为兼容模式，AI 方案可能需要修正；导入图片可保留你原有的视觉设计。')}</p>`:''}<form id="create-form"><div class="two-fields">${selectField('brief.kind',t('Character','角色'),[['','Your choice','自由选择'],['human','Human','人物'],['animal','Animal','动物'],['creature','Imaginary creature','幻想生物'],['object','Object / custom','物体 / 自定义']],b.kind)}${selectField('brief.era',t('World','背景'),[['','Your choice','自由选择'],['historical','Historical','历史'],['modern','Modern','现代'],['imagined','Imagined','想象世界']],b.era)}</div>
${selectField('brief.style',t('Visual style','视觉风格'),[['','Your choice','自由选择'],['traditional-inspired','Traditional-inspired','传统风格启发'],['paper-cut','Paper cut','剪纸'],['graphic','Bold graphic','图形化'],['silhouette','Silhouette','剪影']],b.style)}
${field(t('Your character prompt','你的角色描述'),`<textarea id="create-prompt" rows="5" maxlength="4000" placeholder="${t('Describe identity, costume, silhouette, colors, and what needs to move…','描述身份、服装、轮廓、颜色以及需要活动的部位…')}">${esc(state.prompt||b.keywords)}</textarea>`)}
<div class="prompt-hint">${t('Historical or modern. Real or fictional. Add the features that make your character recognizable.','历史或现代，真实或虚构。写下角色最有辨识度的特征。')}</div>
<button class="primary full" type="submit" ${state.busy?'disabled':''}>${state.busy?t('Thinking…','正在构思…'):state.capabilities?.mode==='drawing-plan'?t('Ask for a drawing plan ↗','请求绘制方案 ↗'):t('Draft an editable puppet ↗','生成可编辑草案 ↗')}</button>
${state.capabilities?.imageGeneration?btn(t('Generate artwork','生成角色图像'),'generate-image','secondary full',state.busy):`<p class="connection-note">${t('Artwork generation needs an image-enabled relay. You can import an image below.','生成角色图像需要启用图像服务的中继。也可以在下方导入图片。')}</p>`}</form>
<div class="divider"><span>${t('or start from an image','或从图片开始')}</span></div>
${btn(`<span class="upload-icon">↑</span><strong>${t('Import your artwork','导入自己的作品')}</strong><small>PNG · JPG · WebP</small>`,'import-art','upload-card')}
<details class="starter-details"><summary>${t('Use a construction template','使用结构模板')}</summary><p>${t('Optional editable starting shapes. Replaces the current parts; Undo is available.','可选的可编辑基础形状。将替换当前部件，可撤销。')}</p><div class="starter-grid">${[['figure','Jointed figure','关节人形'],['skirt','Wide sleeves & skirt','宽袖与裙装'],['winged','Winged creature','翼形生物'],['tentacles','Tentacled character','触手角色']].map(([id,en,zh])=>btn(t(en,zh),'starter','secondary',state.busy,`data-kind="${id}"`)).join('')}</div></details>`;}

function refinePanel(){return `<div class="eyebrow">${t('02 / Make it yours','02 / 修改设计')}</div><h1>${t('Your idea.<br>Your decisions.','你的创意。<br>由你决定。')}</h1><p class="intro">${t('Describe a change. Compare the proposal, then decide what to keep. Lock any part you want to preserve.','描述修改需求，对比方案，再决定是否保留。可以锁定不想改变的部件。')}</p>
<form id="refine-form">${field(t('What would you like to change?','想修改什么？'),`<textarea id="revision-prompt" rows="6" maxlength="4000" placeholder="${t('Make the sleeves wider. Keep the face. Add two articulated wings…','把袖子加宽，保留脸部，再添加两只有关节的翅膀…')}">${esc(state.revisionPrompt)}</textarea>`)}
<button type="submit" class="primary full" ${state.busy||!state.project.parts.length?'disabled':''}>${state.busy?t('Thinking…','正在思考…'):t('Propose changes ↗','提出修改方案 ↗')}</button></form>
<p class="connection-note">${t('Width and length controls reshape the artwork with the piece. New visual details require an image editing connection.','形状修改会改变裁切轮廓；修改导入图片的细节需要图像编辑服务。')}</p>
${state.capabilities?.imageGeneration&&state.project.conceptAssetId?btn(t('Revise the artwork image','修改角色图像'),'edit-image','secondary full',state.busy):''}
${state.project.conceptAssetId?btn(t('Ask AI to review the image','请 AI 检查图片'),'analyze','secondary full',state.busy||!state.capabilities?.vision):''}
<div class="mini-guide"><span class="guide-num">↔</span><div><strong>${t('Compare before applying','应用前先对比')}</strong><p>${t('Suggestions never overwrite your work automatically. Accept, discard, or undo.','建议不会自动覆盖作品。可以接受、放弃或撤销。')}</p></div></div>
<div class="conversation" aria-live="polite">${state.messages.slice(-6).map(m=>`<div class="message ${m.role}"><span>${m.role==='user'?t('You','你'):t('Design assistant','设计助手')}</span><p>${esc(m.content)}</p></div>`).join('')}</div>`;}

function makePanel(){const diagnostics=validateStudio(state.project),errors=diagnostics.filter(d=>d.level==='error');return `<div class="eyebrow">${t('03 / Prepare & export','03 / 制作与导出')}</div><h1>${t('Give your<br>character movement.','让角色<br>动起来。')}</h1><p class="intro">${t('Trace separate pieces, connect them, and test their movement before printing.','描出独立部件，连接关节，打印前测试活动效果。')}</p>
${imageToolsPanel()}<div class="tool-stack">${btn(t('＋ Draw a custom part','＋ 绘制自定义部件'),'draw',state.mode==='draw'?'tool active':'tool')}${btn(t('⊙ Add a connection','⊙ 添加连接'),'joint',state.mode==='joint'?'tool active':'tool',state.project.parts.length<2)}${btn(t('↗ Add a control-rod point','↗ 添加操纵杆连接点'),'rod',state.mode==='rod'?'tool active':'tool',!state.project.parts.length)}</div>
${selectField('jointType',t('Connection type','连接类型'),[['pivot','Pivot · split pin','旋转关节 · 两脚钉'],['fixed','Fixed · glued overlap','固定连接 · 重叠粘接'],['hinge','Pin hinge · planar motion','销轴铰链 · 平面运动']],state.jointType)}
${state.project.conceptAssetId?btn(t('Suggest parts from this image','根据图片建议部件'),'segment','secondary full',state.busy||!state.capabilities?.vision):''}
${state.project.conceptAssetId&&!state.capabilities?.vision?`<p class="connection-note">${t('AI part suggestions are not connected. The local image tools and manual tracing remain available.','尚未连接 AI 部件建议。可以使用本地图像工具或手动描图。')}</p>`:''}<details class="guidance"><summary>${t('How to prepare an imported image','如何处理导入图片')}</summary><ol><li>${t('Remove the plain background, find silhouette pieces, or draw an outline.','去除纯色背景、提取轮廓部件，或手动描出轮廓。')}</li><li>${t('Split a selected piece where it should bend, or connect separate parent and child pieces.','在需要弯曲的位置分割部件，或连接分开的父部件和子部件。')}</li><li>${t('Add control rods, then move each joint with the angle slider.','添加操纵杆连接点，使用角度滑块测试关节。')}</li><li>${t('Check hidden areas: an image cannot show artwork behind an arm or sleeve. Redraw or extend those areas before cutting.','检查遮挡区：图片没有显示手臂或衣袖背后的细节，裁切前需补画或延长。')}</li></ol></details>
<div class="size-settings"><h3>${t('Print size','打印尺寸')}</h3><div class="two-fields">${field(t('Height · mm','高度 · mm'),`<input type="number" min="1" max="1200" step=".1" data-field="heightMm" value="${Number(state.project.heightMm.toFixed(1))}">`)}${field(t('Hole · mm','孔径 · mm'),`<input type="number" min="1" max="12" step=".1" data-field="holeMm" value="${state.project.holeMm}">`)}</div>${field(t('Material thickness · mm','材料厚度 · mm'),`<input type="number" min=".1" max="10" step=".1" data-field="materialMm" value="${state.project.materialMm}">`)}</div>
<div class="checks ${errors.length?'has-error':''}"><h3>${errors.length?t('Resolve before export','导出前需处理'):t('Fabrication checks','制作检查')}</h3>${diagnostics.length?`<ul>${diagnostics.slice(0,10).map(d=>`<li class="${d.level}">${esc(d.message)}</li>`).join('')}</ul>`:`<p>${t('Geometry checks passed. Make a paper prototype to check strength and movement.','几何检查通过。请先制作纸样检查强度与活动效果。')}</p>`}</div>
${btn(t('Print pieces & assembly guide','打印部件与组装指南'),'print','primary full',!state.project.parts.length||!!errors.length)}<div class="two-buttons">${btn(t('Artwork SVG','作品 SVG'),'export-art','secondary',!state.project.parts.length||!!errors.length)}${btn(t('Cut outlines SVG','裁切轮廓 SVG'),'export-cut','secondary',!state.project.parts.length||!!errors.length)}</div><p class="fine-print">${t('Print at 100%. Check the 50 mm calibration mark. Motion preview is planar; material strength and physical assembly still need a prototype.','请按 100% 打印，并检查 50 mm 校准标记。运动预览为平面模拟，材料强度与组装仍需实物试验。')}</p>`;}

function inspector(){const p=selected();const joint=p&&state.project.joints.find(j=>j.childId===p.id);return `<aside class="inspector"><div class="panel-heading"><h2>${t('Your parts','你的部件')}</h2><span class="count">${state.project.parts.length}</span></div><p class="panel-caption">${t('Select a part on the canvas or below.','在画布或列表中选择部件。')}</p><div class="part-list">${state.project.parts.length?state.project.parts.map(part=>`<button class="part-item ${state.selected===part.id?'selected':''}" data-action="select" data-id="${esc(part.id)}"><span class="part-swatch" style="background:${/^#[\da-f]{6}$/i.test(part.fill)?part.fill:'#c78b55'}"></span><span>${esc(part.name)}</span><span>${part.locked?'▣':'›'}</span></button>`).join(''):`<div class="parts-empty">${t('Your character starts here. Import artwork, choose a template, or draw your first piece.','导入作品、选择结构模板或绘制第一个部件，开始设计你的角色。')}</div>`}</div>
${p?`<div class="part-properties"><div class="panel-heading"><h3>${t('Selected part','已选部件')}</h3>${btn(p.locked?t('Unlock','解锁'):t('Lock','锁定'),'lock','small-button')}</div>${field(t('Name','名称'),`<input data-part-field="name" value="${esc(p.name)}" maxlength="80" ${p.locked?'disabled':''}>`)}<div class="two-fields">${field(p.assetId?t('Tab / backing color','连接片 / 衬底颜色'):t('Color','颜色'),`<input type="color" data-part-field="fill" value="${esc(p.fill||'#bc7653')}" ${p.locked?'disabled':''}>`)}${field(t('Layer','图层'),`<input type="number" data-part-field="z" value="${p.z||0}" min="-80" max="80" ${p.locked?'disabled':''}>`)}</div>
${state.project.assets.length?field(t('Artwork','图像来源'),`<select data-part-field="assetId" ${p.locked?'disabled':''}><option value="">${t('Solid color','纯色')}</option>${state.project.assets.map(a=>`<option value="${esc(a.id)}" ${p.assetId===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select>`):''}
${dimensionControls(p)}${!joint?`<div class="two-fields">${field('X',`<input type="number" data-part-field="x" value="${p.x||0}" ${p.locked?'disabled':''}>`)}${field('Y',`<input type="number" data-part-field="y" value="${p.y||0}" ${p.locked?'disabled':''}>`)}</div>`:''}
${btn(t('Edit outline points','编辑轮廓点'),'vertices',state.mode==='vertices'?'secondary full active':'secondary full',p.locked)}${joint?`<div class="joint-control"><h3>${t('Connection & movement','连接与运动')}</h3>${selectField('connection.type',t('Type','类型'),[['pivot','Pivot','旋转'],['fixed','Fixed','固定'],['hinge','Pin hinge','销轴铰链']],joint.type,p.locked?'disabled':'')}${field(t('Angle','角度')+` <output id="angle-output">${joint.angle}°</output>`,`<input type="range" data-joint-field="angle" min="${joint.min}" max="${joint.max}" step="1" value="${joint.angle}" ${p.locked||joint.type==='fixed'?'disabled':''}>`)}<div class="two-fields">${field(t('Min °','最小角度'),`<input type="number" data-joint-field="min" min="-180" max="180" value="${joint.min}" ${p.locked?'disabled':''}>`)}${field(t('Max °','最大角度'),`<input type="number" data-joint-field="max" min="-180" max="180" value="${joint.max}" ${p.locked?'disabled':''}>`)}</div>${field(t('Overlap radius · mm','重叠半径 · mm'),`<input type="number" data-joint-field="padRadius" min="0" max="${300/unitsPerMm(state.project)}" step=".1" value="${Number((joint.padRadius/unitsPerMm(state.project)).toFixed(2))}" ${p.locked?'disabled':''}>`)}${btn(t('Remove connection','移除连接'),'remove-joint','text-button danger',p.locked)}</div>`:''}
${btn(t('Split into hinged pieces','分割成铰接部件'),'split-part','secondary full',p.locked)}${connectionSuggestion(p)}${btn(t('Duplicate part','复制部件'),'duplicate','secondary full',p.locked)}${btn(t('Delete part','删除部件'),'delete-part','text-button danger full',p.locked)}</div>`:''}
${state.project.rods.length?`<details class="rod-list"><summary>${t('Control rods','操纵杆')} · ${state.project.rods.length}</summary>${state.project.rods.map(r=>`<div>${esc(state.project.parts.find(p=>p.id===r.partId)?.name||'Part')}${btn('×','remove-rod','small-button',false,`data-id="${esc(r.id)}" aria-label="${t('Remove rod','删除操纵杆')}"`)}</div>`).join('')}</details>`:''}
<div class="inspector-footer"><strong>${t('Designed by you','由你设计')}</strong><p>${t('AI suggests. You choose, revise, and make.','AI 提出建议，你来选择、修改和制作。')}</p></div></aside>`;}

function canvasContent(project=state.project,mini=false,display={}){const frame=projectBounds(project),w=Math.max(project.canvas.width,frame.maxX||0),h=Math.max(project.canvas.height,frame.maxY||0),x=Math.min(0,frame.minX||0),y=Math.min(0,frame.minY||0);const imageOnly=display.imageOnly===true||(!mini&&state.mode==='region');let svg=renderStudioSvg(imageOnly?{...project,parts:[],joints:[],rods:[]}:project,{selectedPartId:mini?null:state.selected,showJoints:state.showJoints,showRods:true,showArt:display.showArt??state.showArt,showConcept:(display.showConcept??state.showConcept)&&(display.showArt??state.showArt),interactive:!mini,draftPoints:[],...(!mini?{viewBox:imageOnly?[0,0,project.canvas.width,project.canvas.height]:[x-60,y-60,w-x+120,h-y+120]}:{})});if(mini)return svg;let overlay='';if(state.points.length){overlay+=`<g class="trace-overlay"><polyline points="${state.points.map(p=>p.join(',')).join(' ')}"/><g>${state.points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="5"/><text x="${x+8}" y="${y-8}">${i+1}</text>`).join('')}</g></g>`;}
if(state.mode==='vertices'&&selected()){const p=selected(),matrix=partTransforms(project)[p.id];overlay+=`<g class="vertex-overlay">${p.polygon.map((point,i)=>{const [x,y]=transformPoint(matrix,point);return `<circle data-vertex-index="${i}" cx="${x}" cy="${y}" r="7" aria-label="Point ${i+1}"/>`;}).join('')}</g>`;}
if(state.jointStart){const matrix=partTransforms(project)[state.jointStart.partId],point=transformPoint(matrix,state.jointStart.point);overlay+=`<circle class="anchor-pending" cx="${point[0]}" cy="${point[1]}" r="10"/>`;}
return svg.replace('</svg>',overlay+'</svg>');}
function toolHint(){if(state.mode==='split')return `<strong>${t('Place two points across the selected piece','在所选部件两侧放置两个点')}</strong><span>${t('The cut follows the line between them. A pivot and overlap tabs will be proposed.','裁切沿两点连线进行，并建议转轴和重叠连接片。')}</span>${btn(t('Undo point','撤销点'),'undo-point','small-button',!state.points.length)}${btn(t('Preview split','预览分割'),'preview-split','primary small-button',state.points.length!==2)}${btn('×','cancel-tool','small-button')}`;if(state.mode==='axis')return `<strong>${t('Click two points along the length direction','沿长度方向点击两个点')}</strong><span>${t('The current artwork stays unchanged.','当前图像保持不变。')}</span>${btn('×','cancel-tool','small-button')}`;if(state.mode==='region')return `<strong>${t('Click a connected color region in the original image','点击原图中连通的颜色区域')}</strong><span>${t('This selects similar pixels, not body parts. Adjust tolerance if needed.','此工具选择相似像素，不识别身体部件。可按需调整容差。')}</span>${btn('×','cancel-tool','small-button')}`;if(state.mode==='draw')return `<strong>${t('Trace the boundary','描出轮廓')}</strong><span>${t('Click around a piece. Finish with at least 3 points.','沿部件边界点击，至少绘制 3 个点后完成。')}</span>${btn(t('Undo point','撤销点'),'undo-point','small-button',!state.points.length)}${btn(t('Finish part','完成部件'),'finish-part','primary small-button',state.points.length<3)}${btn('×','cancel-tool','small-button')}`;if(state.mode==='joint')return `<strong>${state.jointStart?t('2. Choose the child’s pivot','2. 选择子部件的转轴点'):t('1. Choose the parent’s pivot','1. 选择父部件的转轴点')}</strong><span>${t('Click a point inside each piece. Overlapping pieces can be selected in the parts list first.','在两个部件内部各点击一点。重叠部件可先从列表选择。')}</span>${btn('×','cancel-tool','small-button')}`;if(state.mode==='rod')return `<strong>${t('Click a control-rod attachment point','点击操纵杆连接位置')}</strong>${btn('×','cancel-tool','small-button')}`;if(state.mode==='vertices')return `<strong>${t('Drag the outline points','拖动轮廓点')}</strong><span>${t('Keep the boundary simple, without crossing edges.','保持轮廓简单，避免边线交叉。')}</span>${btn(t('Done','完成'),'cancel-tool','small-button')}`;return '';}
function proposalView(){if(!state.proposal)return '';const display=state.proposalAfter?.imageReview?{imageOnly:true,showArt:true,showConcept:true}:{};return `<section class="proposal-review ${state.proposalAfter?.imageReview?'image-review':''}" aria-label="${t('Review proposal','审核方案')}"><div class="proposal-heading"><div><span class="eyebrow">${t('YOUR DECISION','由你决定')}</span><h2>${t('Review the proposed design','审核设计方案')}</h2></div>${btn('×','reject','small-button',false,`aria-label="${t('Discard proposal','放弃方案')}"`)}</div><p>${esc(state.reply)}</p><div class="comparison"><div><span>${t('Before','修改前')}</span>${canvasContent(state.proposalBase,true,display)}</div><div><span>${t('Proposed','建议方案')}</span>${canvasContent(state.proposal,true,display)}</div></div><div class="proposal-actions">${btn(t('Discard','放弃'),'reject','secondary')}${btn(t('Accept this design','接受此设计'),'accept','primary')}</div></section>`;}
function settingsView(){return `<div class="modal-backdrop"><section class="settings-card" role="dialog" aria-modal="true" aria-label="AI connection"><div class="panel-heading"><h2>${t('AI connection','AI 连接')}</h2>${btn('×','settings','small-button')}</div><p>${t('Use a protected studio relay URL. API keys belong on the server and are never entered here.','使用受保护的工作室中继地址。API 密钥仅保存在服务器端，不在此输入。')}</p>${field(t('Protected endpoint','受保护的接口地址'),`<input id="relay-url" type="url" placeholder="https://your-relay.example/api/studio" value="${esc(state.endpoint)}">`)}${btn(t('Save & check connection','保存并检查连接'),'save-endpoint','primary full')}<div class="capability-list">${['text','vision','imageGeneration'].map(key=>`<div><span>${t({text:'Editable design proposals',vision:'Image analysis',imageGeneration:'Image generation / editing'}[key],{text:'可编辑设计方案',vision:'图片分析',imageGeneration:'图像生成 / 编辑'}[key])}</span><strong>${state.capabilities?.[key]?t('Available','可用'):t('Not available','不可用')}</strong></div>`).join('')}</div><p class="fine-print">${esc(state.capabilities?.status||state.capabilities?.message||'')}</p><a href="https://github.com/zhinii/bnta-shadow-puppet-studio/blob/main/integration/STUDIO-V2-RELAY.md" target="_blank" rel="noopener">${t('Relay setup instructions','中继配置说明')}</a></section></div>`;}

function render(){document.documentElement.lang=state.project.language;root.innerHTML=`<header class="topbar"><a class="brand" href="#" aria-label="Shadow Puppet Studio"><span class="brand-mark">影</span><span>${t('Shadow Puppet Studio','光影设计工作室')}<small>BNTA · ${t('Imagine. Revise. Make.','构思 · 修改 · 制作')}</small></span></a><input class="project-title" data-field="title" maxlength="100" value="${esc(state.project.title)}" placeholder="${t('Untitled puppet','未命名角色')}" aria-label="${t('Project title','项目名称')}"><div class="top-actions"><span id="save-status" class="save-status"></span>${btn('↶','undo','icon-button',!state.undo.length,`title="${t('Undo','撤销')}" aria-label="${t('Undo','撤销')}"`)}${btn('↷','redo','icon-button',!state.redo.length,`title="${t('Redo','重做')}" aria-label="${t('Redo','重做')}"`)}${btn(t('Open','打开'),'open-project','top-button')}${btn(t('Save project','保存项目'),'save-project','top-button save-button')}${btn(state.project.language==='en'?'中文':'EN','language','top-button')}</div></header>
<nav class="steps" aria-label="${t('Design process','设计流程')}">${[['create','Create','构思'],['refine','Refine','修改'],['make','Prepare & export','制作与导出']].map(([id,en,zh],i)=>`<button class="step ${state.step===id?'current':''}" data-action="step" data-step="${id}" ${state.step===id?'aria-current="step"':''}><span class="step-number">0${i+1}</span><span>${t(en,zh)}</span><span class="step-arrow">→</span></button>`).join('')}<div class="nav-spacer"></div>${btn(t('Connection','连接'),'settings','connection-button')}${btn(t('New project','新建项目'),'new-project','text-button')}</nav>
<main class="workspace"><section class="work-panel">${state.step==='create'?createPanel():state.step==='refine'?refinePanel():makePanel()}</section><section class="canvas-panel"><div class="canvas-toolbar"><div class="view-switch">${btn(t('Artwork','作品'),'view-art',state.showArt?'active':'')}${btn(t('Shadow','剪影'),'view-shadow',!state.showArt?'active':'')}</div><div class="view-options"><label><input type="checkbox" data-view="joints" ${state.showJoints?'checked':''}>${t('Joints','关节')}</label>${state.project.conceptAssetId?`<label><input type="checkbox" data-view="concept" ${state.showConcept?'checked':''}>${t('Reference','参考图')}</label>`:''}</div><span class="canvas-scale">${Number(state.project.heightMm.toFixed(1))} mm</span></div>
${state.error?`<div class="error-banner" role="alert">${esc(state.error)}${btn('×','dismiss-error','small-button')}</div>`:''}
${state.busy?`<div class="busy-banner" role="status"><span class="spinner"></span>${t('Working on your request…','正在处理请求…')}${btn(t('Cancel','取消'),'cancel-ai','text-button')}</div>`:''}
<div class="canvas-wrap ${!state.showArt?'shadow-view':''} mode-${state.mode}" id="canvas-wrap"><div class="canvas-corner top-left"></div><div class="canvas-corner bottom-right"></div><div id="puppet-canvas">${canvasContent()}</div>${!state.project.parts.length&&!state.project.assets.length?`<div class="empty-canvas"><span class="empty-emblem">光 · 影</span><h2>${t('A stage for your imagination','让想象登场')}</h2><p>${t('Every character begins with an idea.<br>Start in the panel on the left.','每个角色都从一个想法开始。<br>请从左侧开始构思。')}</p>${btn(t('Draw a custom shape','绘制自定义形状'),'draw','secondary')}</div>`:''}</div>
${state.mode!=='select'?`<div class="tool-hint" role="status">${toolHint()}</div>`:''}<div class="canvas-footer"><span>${state.project.parts.length} ${t('parts','部件')} <i>·</i> ${state.project.joints.length} ${t('connections','连接')}</span><span>${t('Your choices shape the character.','由你定义角色。')}</span></div>${proposalView()}</section>${inspector()}</main><footer class="page-footer"><span>${t('From an idea to a puppet you can make.','从创意到可制作的皮影。')}</span><a href="${new URL('./legacy.html',import.meta.url).href}">${t('Open earlier projects in the classic editor','在旧版编辑器中打开以前的项目')}</a></footer>${state.settings?settingsView():''}`;status();}

async function checkConnection(){try{state.capabilities=await getStudioCapabilities(state.endpoint?{endpoint:state.endpoint}:{});}catch(error){state.capabilities={text:false,vision:false,imageGeneration:false,message:error.message};}render();}
async function aiRequest(task){if(state.busy)return;const prompt=task==='create'||task==='generate-image'?state.prompt||state.project.brief.keywords:state.revisionPrompt;
if(!prompt.trim()&&!['segment','analyze'].includes(task)){state.error=t('Describe your character or the change you want first.','请先描述角色或修改需求。');render();return;}
if(task==='refine'&&!state.project.parts.length)return;
const asset=state.project.assets.find(a=>a.id===state.project.conceptAssetId);const requestPrompt=prompt|| (task==='segment'?t('Suggest separate movable puppet parts for this artwork. Preserve the silhouette and visible details.','为此图像建议独立的可活动皮影部件，保留轮廓和可见细节。'):t('Review this character as a physical shadow puppet: identify movement, connections, hidden overlap artwork, and fragile areas.','检查此角色作为实体皮影的可行性：分析活动、连接、遮挡的重叠区域和脆弱部位。'));
if(task==='create'&&state.project.parts.some(p=>p.locked)){state.error=t('Create replaces the design. Unlock parts first, or use Refine to keep them.','构思将替换设计。请先解锁部件，或使用修改功能保留它们。');render();return;}
const original=structuredClone(state.project),base=structuredClone(state.project),version=state.version;if(task==='create'){base.parts=[];base.joints=[];base.rods=[];base.revisions=[];}state.busy=true;state.error='';state.proposal=null;state.proposalLabel='';state.proposalAfter=null;state.proposalVersion=version;controller=new AbortController();const timeout=setTimeout(()=>controller?.abort(),['generate-image','edit-image'].includes(task)?240000:150000);state.messages.push({role:'user',content:requestPrompt});render();
try{const sendImage=['analyze','segment','edit-image','generate-image'].includes(task)||state.capabilities?.vision;const result=await requestStudioAI(base,{task,prompt:requestPrompt,selectedPartId:task==='refine'?state.selected:null,imageDataUrl:sendImage?asset?.dataUrl:undefined,history:state.messages.slice(-5),signal:controller.signal,...(state.endpoint?{endpoint:state.endpoint}:{})});if(controller.signal.aborted)return;state.reply=result.reply;state.messages.push({role:'assistant',content:result.reply});if(version!==state.version){state.error=t('The design changed while AI was working. Please request a fresh proposal.','AI 工作期间设计已更改，请重新请求方案。');return;}
let proposal=null;if(result.asset){const normalizedAsset={...result.asset,id:result.asset.id||uid()};base.assets.push(normalizedAsset);if(task==='edit-image'&&asset){if(asset.width!==normalizedAsset.width||asset.height!==normalizedAsset.height){result.warnings=[...(result.warnings||[]),t('Image framing changed. Existing part artwork is preserved; trace the new reference to align new parts.','图像尺寸已改变。已保留原部件图像，请根据新参考图重新描绘部件。')];}else{for(const part of base.parts)if(!part.locked&&part.assetId===asset.id)part.assetId=normalizedAsset.id;result.warnings=[...(result.warnings||[]),t('Check the cut edges against the revised artwork; pixel edits may shift details.','请检查裁切轮廓与修改后图像的对应关系，图像修改可能改变细节位置。')];}}base.conceptAssetId=normalizedAsset.id;base.canvas={width:normalizedAsset.width,height:normalizedAsset.height};proposal=base;}
if(result.proposal){proposal=applyStudioProposal(base,result.proposal);if(task!=='create')proposal=preservePhysicalScale(original,proposal);}
if(proposal){state.proposal=normalizeStudioProject(proposal);state.proposalBase=original;}else if(!result.reply){state.error=t('No design was returned. Your work is unchanged.','未返回设计，当前作品保持不变。');}if(result.warnings?.length)state.error=result.warnings.join(' ');if(task==='analyze'){state.step='refine';toast(t('Image review added to the conversation.','图片分析已添加至对话。'));}}
catch(error){state.error=error.name==='AbortError'?t('Request cancelled. Your work is unchanged.','请求已取消，作品未更改。'):error.message;}
finally{clearTimeout(timeout);state.busy=false;controller=null;render();}}

function screenPoint(event){const svg=document.querySelector('#puppet-canvas svg');if(!svg)return null;const p=svg.createSVGPoint();p.x=event.clientX;p.y=event.clientY;const matrix=svg.getScreenCTM();if(!matrix)return null;const result=p.matrixTransform(matrix.inverse());return [Math.round(result.x*10)/10,Math.round(result.y*10)/10];}
function localPoint(partId,point){const m=partTransforms(state.project)[partId],det=m[0]*m[3]-m[1]*m[2];if(!det)throw Error('Invalid transform');const x=point[0]-m[4],y=point[1]-m[5];return [(m[3]*x-m[2]*y)/det,(-m[1]*x+m[0]*y)/det];}
function canvasClick(event){if(drag?.moved)return;const point=screenPoint(event);if(!point)return;const hit=event.target.closest('[data-part-id]')?.dataset.partId;const partId=state.mode==='select'?hit:state.selected||hit;
if(state.mode==='region'){runImageTool('select-region',point.map(Math.round));return;}if(state.mode==='split'||state.mode==='axis'){if(!selected()||selected().locked)return;if(state.points.length===2)state.points=[];state.points.push(point);if(state.mode==='axis'&&state.points.length===2){try{const a=localPoint(state.selected,state.points[0]),b=localPoint(state.selected,state.points[1]);if(Math.hypot(b[0]-a[0],b[1]-a[1])<2)throw Error(t('Choose two distinct points.','请选择两个不同的点。'));const angle=Math.atan2(b[1]-a[1],b[0]-a[0])*180/Math.PI-90;const next=setPartParameterAxis(state.project,state.selected,((angle+540)%360)-180);resetTool();commit(next,t('Set part direction','设置部件方向'));}catch(error){state.error=error.message;render();}}else render();return;}if(state.mode==='draw'){if(state.points.length>=500){toast('Finish this outline before adding more points.');return;}state.points.push(point);render();return;}if(state.mode==='joint'&&partId){const part=state.project.parts.find(p=>p.id===partId);if(part?.locked){toast(t('Unlock this part first.','请先解锁此部件。'));return;}if(!state.jointStart){state.jointStart={partId,point:localPoint(partId,point)};state.selected=null;render();return;}if(partId===state.jointStart.partId){toast(t('Choose a different child part.','请选择另一个子部件。'));return;}try{const next=addConnection(state.project,{id:uid(),parentId:state.jointStart.partId,childId:partId,parentAnchor:state.jointStart.point,childAnchor:localPoint(partId,point),type:state.jointType,angle:0,min:-90,max:90,padRadius:unitsPerMm(state.project)*(state.jointType==='fixed'?Math.max(3,state.project.materialMm+1):state.project.holeMm/2+Math.max(1,state.project.materialMm)+.5)});resetTool();state.selected=partId;commit(preservePhysicalScale(state.project,next),t('Add connection','添加连接'));}catch(e){state.error=e.message;render();}return;}
if(state.mode==='rod'&&partId){const p=state.project.parts.find(p=>p.id===partId);if(p.locked){toast(t('Unlock this part first.','请先解锁部件。'));return;}const local=localPoint(partId,point);resetTool();mutate(next=>next.rods.push({id:uid(),partId,point:local}),t('Add rod point','添加操纵杆连接点'));return;}
if(state.mode==='select'){if(state.selected!==hit)state.connectParent='';state.selected=hit||null;render();}}

root.addEventListener('click',async event=>{if(event.target.closest('#puppet-canvas')){canvasClick(event);return;}const el=event.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;try{
if(a==='step'){resetTool();state.step=el.dataset.step;render();}
else if(a==='language'){mutate(p=>{p.language=p.language==='en'?'zh':'en';},'Language');}
else if(a==='select'){resetTool();state.connectParent='';state.selected=el.dataset.id;render();}
else if(a==='undo'||a==='redo'){const from=a==='undo'?state.undo:state.redo,to=a==='undo'?state.redo:state.undo;if(from.length){to.push(state.project);state.project=from.pop();state.version++;state.proposal=null;resetTool();scheduleSave();render();}}
else if(a==='save-project'){download(safeName()+'.puppet.json',serializeStudioProject(state.project),'application/json');toast(t('Project downloaded with its artwork.','项目及作品图片已下载。'));}
else if(a==='open-project')document.querySelector('#project-file').click();
else if(a==='import-art')document.querySelector('#artwork-file').click();
else if(a==='new-project'){if(state.project.parts.length||state.project.assets.length){download(safeName()+'.puppet.json',serializeStudioProject(state.project),'application/json');}const language=state.project.language;commit({...createStudioProject(),language},t('New project (previous work downloaded)','新建项目（已下载旧作品）'));state.step='create';state.prompt='';state.revisionPrompt='';resetTool();render();}
else if(a==='starter'){if(state.project.parts.some(p=>p.locked))throw Error(t('Unlock the current parts before replacing the construction.','替换结构前请先解锁当前部件。'));const next=createStarter(el.dataset.kind,{language:state.project.language});next.title=state.project.title;next.brief=state.project.brief;next.assets=state.project.assets;next.conceptAssetId=state.project.conceptAssetId;commit(next,t('Choose construction template','选择结构模板'));state.selected=next.parts[0]?.id;state.showConcept=false;render();}
else if(a==='view-art'||a==='view-shadow'){state.showArt=a==='view-art';render();}
else if(a==='remove-background'||a==='extract-silhouette')await runImageTool(a);
else if(a==='select-region'){state.showArt=true;state.showConcept=true;state.selected=null;beginTool('region');}
else if(a==='split-part'&&selected()&&!selected().locked)beginTool('split');
else if(a==='parameter-axis'&&selected()&&!selected().locked)beginTool('axis');
else if(a==='preview-split'&&selected()&&state.points.length===2){const points=state.points.map(p=>localPoint(state.selected,p));const result=splitPart(state.project,state.selected,points[0],points[1],{connect:true,type:state.jointType});resetTool();proposeLocal(result.project,t('Split into hinged pieces','分割成铰接部件'),t('Review the two pieces and their shared pivot. Overlap tabs support the joint; check the printed detail in that area before cutting.','请检查两个部件及其共用转轴。重叠连接片为关节提供支撑，裁切前请检查该区域的图像细节。')+' '+(result.warnings||[]).join(' '),{selected:result.partIds[1],showConcept:false,step:'make'});}
else if(a==='suggest-connection'&&selected()&&state.connectParent){const result=suggestConnection(state.project,state.connectParent,state.selected,{type:state.jointType});proposeLocal(result.project,t('Accept suggested connection','接受建议连接'),t('This pivot was suggested from the chosen pieces and their distance, not anatomical recognition. Review its position and movement.','此转轴根据所选部件及其距离计算，并非解剖识别结果。请检查其位置与运动。')+' '+(result.warnings||[]).join(' '),{showConcept:false,step:'make'});}
else if(['draw','joint','rod'].includes(a))beginTool(a);
else if(a==='cancel-tool'){resetTool();render();}
else if(a==='undo-point'){state.points.pop();render();}
else if(a==='finish-part'){if(state.points.length<3)return;const part=makePart(t('Part ','部件 ')+(state.project.parts.length+1),state.points,state.project.conceptAssetId);const next=structuredClone(state.project);next.parts.push(part);resetTool();state.selected=part.id;commit(preservePhysicalScale(state.project,next),t('Draw custom part','绘制自定义部件'));}
else if(a==='vertices'){const mode=state.mode==='vertices'?'select':'vertices';resetTool();state.mode=mode;render();}
else if(a==='lock'){mutate(p=>{const part=p.parts.find(x=>x.id===state.selected);part.locked=!part.locked;},t('Lock / unlock part','锁定 / 解锁部件'));}
else if(a==='duplicate'&&selected()&&!selected().locked){const part=structuredClone(selected()),matrix=partTransforms(state.project)[part.id];part.id=uid();part.name+=' '+t('copy','副本');part.x=matrix[4]+25;part.y=matrix[5]+25;part.rotation=Math.atan2(matrix[1],matrix[0])*180/Math.PI;state.selected=part.id;mutate(p=>p.parts.push(part),t('Duplicate part','复制部件'));}
else if(a==='delete-part'&&selected()&&!selected().locked){const id=state.selected,transforms=partTransforms(state.project);mutate(p=>{for(const joint of p.joints.filter(j=>j.parentId===id)){const child=p.parts.find(p=>p.id===joint.childId);if(child.locked)throw Error(t('Unlock connected child parts before deleting their parent.','删除父部件前请先解锁连接的子部件。'));const m=transforms[child.id];child.x=m[4];child.y=m[5];child.rotation=Math.atan2(m[1],m[0])*180/Math.PI;}p.parts=p.parts.filter(x=>x.id!==id);p.joints=p.joints.filter(j=>j.parentId!==id&&j.childId!==id);p.rods=p.rods.filter(r=>r.partId!==id);},t('Delete part','删除部件'));}
else if(a==='remove-joint'&&selected()&&!selected().locked){const m=partTransforms(state.project)[state.selected];mutate(p=>{p.joints=p.joints.filter(j=>j.childId!==state.selected);const part=p.parts.find(x=>x.id===state.selected);part.x=m[4];part.y=m[5];part.rotation=Math.atan2(m[1],m[0])*180/Math.PI;},t('Remove connection','移除连接'));}
else if(a==='remove-rod')mutate(p=>{p.rods=p.rods.filter(r=>r.id!==el.dataset.id);},t('Remove rod','移除操纵杆'));
else if(a==='accept'&&state.proposal){if(state.proposalVersion!==null&&state.proposalVersion!==state.version)throw Error(t('The project changed. Review a fresh proposal.','项目已改变，请重新审核方案。'));const proposal=state.proposal,after=state.proposalAfter;commit(proposal,state.proposalLabel||t('Accept AI proposal','接受 AI 方案'));state.proposalLabel='';state.proposalAfter=null;state.proposalVersion=null;state.showConcept=true;if(after){const {imageReview,...updates}=after;Object.assign(state,updates);}render();}
else if(a==='reject'){state.proposal=null;state.proposalLabel='';state.proposalAfter=null;state.proposalVersion=null;render();}
else if(a==='dismiss-error'){state.error='';render();}
else if(a==='cancel-ai')controller?.abort();
else if(['segment','analyze','generate-image','edit-image'].includes(a))await aiRequest(a);
else if(a==='print'){const html=exportPrintHtml(state.project);const frame=document.querySelector('#print-frame');frame.onload=()=>{const doc=frame.contentDocument;Promise.all(Array.from(doc.images||[]).map(img=>img.decode?.().catch(()=>{})||Promise.resolve())).then(()=>{frame.contentWindow.focus();frame.contentWindow.print();});};frame.srcdoc=html;}
else if(a==='export-art'||a==='export-cut')download(safeName()+(a==='export-cut'?'-cut':'-artwork')+'.svg',exportSheetSvg(state.project,{cutOnly:a==='export-cut'}),'image/svg+xml');
else if(a==='settings'){state.settings=!state.settings;render();}
else if(a==='save-endpoint'){const value=document.querySelector('#relay-url').value.trim();if(value){const url=new URL(value);if(url.protocol!=='https:'&&!['localhost','127.0.0.1'].includes(url.hostname))throw Error(t('Use an HTTPS protected relay URL.','请使用 HTTPS 中继地址。'));if(url.username||url.password||url.search||url.hash)throw Error(t('Use a URL without credentials or query parameters.','地址中不能含有凭据或查询参数。'));}state.endpoint=value;try{localStorage.setItem('bnta-studio-endpoint',value);}catch{}await checkConnection();}
}catch(error){state.error=error.message;render();}});

root.addEventListener('input',event=>{const el=event.target;if(el.dataset.imageTolerance!==undefined){state.imageTolerance=Number(el.value);const out=document.querySelector('#tolerance-output');if(out)out.textContent=el.value;return;}if(el.dataset.paramField&&selected()&&!selected().locked){const key=el.dataset.paramField;try{const preview=resizePart(state.project,state.selected,{[key]:Number(el.value)/100});const out=document.querySelector('#parameter-'+key+'-output');if(out)out.textContent=el.value+'%';document.querySelector('#puppet-canvas').innerHTML=canvasContent(preview);}catch{}return;}if(el.id==='create-prompt'){state.prompt=el.value;state.project={...state.project,brief:{...state.project.brief,keywords:el.value}};state.version++;scheduleSave();}if(el.id==='revision-prompt')state.revisionPrompt=el.value;if(el.dataset.jointField==='angle'){const out=document.querySelector('#angle-output');if(out)out.textContent=el.value+'°';const preview=structuredClone(state.project),joint=preview.joints.find(j=>j.childId===state.selected);if(joint){joint.angle=Number(el.value);document.querySelector('#puppet-canvas').innerHTML=canvasContent(preview);}}});
root.addEventListener('change',event=>{const el=event.target;try{if(el.dataset.imageTolerance!==undefined){state.imageTolerance=Number(el.value);return;}if(el.dataset.connectParent!==undefined){state.connectParent=el.value;render();return;}if(el.dataset.paramField&&selected()&&!selected().locked){const next=resizePart(state.project,state.selected,{[el.dataset.paramField]:Number(el.value)/100});commit(next,t('Resize artwork and part','调整图像和部件尺寸'));return;}if(el.dataset.paramAxis!==undefined&&selected()&&!selected().locked){commit(setPartParameterAxis(state.project,state.selected,Number(el.value)),t('Set part direction','设置部件方向'));return;}if(el.dataset.sourceArt!==undefined){const asset=state.project.assets.find(a=>a.id===el.value);if(!asset)return;mutate(p=>{p.conceptAssetId=asset.id;p.canvas={width:asset.width,height:asset.height};},t('Choose source image','选择原始图像'));state.showArt=true;state.showConcept=true;resetTool();render();return;}if(el.dataset.view){if(el.dataset.view==='joints')state.showJoints=el.checked;else state.showConcept=el.checked;render();return;}if(el.dataset.field==='jointType'){state.jointType=el.value;return;}if(el.dataset.field==='connection.type'){if(selected()?.locked)return;mutate(p=>{const j=p.joints.find(j=>j.childId===state.selected);const wasFixed=j.type==='fixed';j.type=el.value;if(j.type==='fixed')j.angle=0;else if(wasFixed&&j.min===j.max){j.min=-90;j.max=90;}},t('Change connection','修改连接'));return;}if(el.dataset.field){const path=el.dataset.field,value=el.type==='number'?Number(el.value):el.value;mutate(p=>{if(path.startsWith('brief.'))p.brief[path.slice(6)]=value;else p[path]=value;},t('Update design settings','修改设计设置'),{keepScale:path!=='heightMm'});return;}if(el.dataset.partField&&selected()&&!selected().locked){const key=el.dataset.partField,value=['x','y','z'].includes(key)?Number(el.value):el.value;mutate(p=>{p.parts.find(x=>x.id===state.selected)[key]=key==='assetId'?(value||null):value;},t('Edit part','编辑部件'));return;}if(el.dataset.jointField&&selected()&&!selected().locked){const key=el.dataset.jointField;mutate(p=>{const j=p.joints.find(j=>j.childId===state.selected);j[key]=Number(el.value)*(key==='padRadius'?unitsPerMm(state.project):1);if(j.min>j.max)throw Error(t('Minimum angle must be below maximum.','最小角度必须小于最大角度。'));j.angle=Math.max(j.min,Math.min(j.max,j.angle));},t('Adjust connection','调整连接'));}}catch(error){state.error=error.message;render();}});
root.addEventListener('submit',event=>{event.preventDefault();if(event.target.id==='create-form'){state.project={...state.project,brief:{...state.project.brief,keywords:state.prompt}};scheduleSave();aiRequest('create');}if(event.target.id==='refine-form')aiRequest('refine');});
root.addEventListener('pointerdown',event=>{const el=event.target.closest('[data-vertex-index]');if(!el||state.mode!=='vertices'||!selected()||selected().locked)return;event.preventDefault();drag={partId:state.selected,index:Number(el.dataset.vertexIndex),start:screenPoint(event),point:null,moved:false};});
document.addEventListener('pointermove',event=>{if(!drag)return;const point=screenPoint(event);if(!point)return;drag.point=localPoint(drag.partId,point);drag.moved=true;const dot=document.querySelector(`[data-vertex-index="${drag.index}"]`);if(dot){dot.setAttribute('cx',point[0]);dot.setAttribute('cy',point[1]);}});
document.addEventListener('pointerup',()=>{if(!drag)return;const d=drag;drag=null;if(d.moved&&d.point){try{mutate(p=>{p.parts.find(p=>p.id===d.partId).polygon[d.index]=d.point;},t('Edit outline','编辑轮廓'));}catch(error){state.error=error.message;render();}}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){controller?.abort();resetTool();state.settings=false;render();}if(event.key==='Enter'&&state.mode==='draw'&&!/INPUT|TEXTAREA|SELECT/.test(event.target.tagName)){event.preventDefault();root.querySelector('[data-action="finish-part"]')?.click();}});
document.querySelector('#project-file').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>55*1024*1024)throw Error('Project file is too large.');const project=parseStudioProject(await file.text());commit(project,t('Open project','打开项目'));state.prompt=project.brief.keywords;state.step=project.parts.length?'make':'create';resetTool();render();}catch(error){state.error=error.message;render();}finally{event.target.value='';}});
document.querySelector('#artwork-file').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{const asset=await readArtworkFile(file);mutate(p=>{p.assets.push(asset);p.conceptAssetId=asset.id;p.canvas={width:asset.width,height:asset.height};},t('Import artwork','导入作品'));resetTool();state.selected=null;state.connectParent='';state.showArt=true;state.showConcept=true;state.step='make';render();toast(t('Use Image to pieces to remove the background or select an outline. You can also draw a custom part.','使用图像转部件工具去除背景或选取轮廓，也可以绘制自定义部件。'));}catch(error){state.error=error.message;render();}finally{event.target.value='';}});
window.addEventListener('beforeunload',event=>{if(state.saveStatus==='saving'||state.saveStatus==='error'){event.preventDefault();event.returnValue='';}});
render();
async function initialize(){try{const saved=await loadStudioProject();if(saved){state.project=saved;state.prompt=saved.brief.keywords;state.step=saved.parts.length?'make':'create';}state.saveStatus='saved';}catch{state.saveStatus='unsaved';}try{state.endpoint=localStorage.getItem('bnta-studio-endpoint')||'';}catch{}render();checkConnection();}
initialize();
